(function(root){
'use strict';
const DT=1/120,R=10,VX=150,G=820,FLAP=-290;
const unsupported=['horizontal_armor_slider','hero_rotor','swing_armor_hammer','patrol_spike_rotor','ring_projectile_core','suction_core','push_pulse_core','laser_scanner','timed_armor_gate','burst_turret','warning_missile','phase_wall','paired_portal','crack_bumper_panel'];
const supported=['fixed_armor_or_spike','vertical_armor_slider','warning_drop_spike','spring_wall'];
const registry=Object.fromEntries([...supported.map(k=>[k,{supported:true}]),...unsupported.map(k=>[k,{supported:false}])]);
function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
function validate(map){if(map.schema!=='flappy-loop-lab/1')throw Error('Unsupported independent schema');if(!Number.isFinite(map.width)||map.width<100||map.height!==540)throw Error('Invalid dimensions');const ids=new Set();for(const o of map.obstacles){if(!registry[o.mechanic_kind]?.supported)throw Error('Unsupported mechanic: '+o.mechanic_kind);if(ids.has(o.id))throw Error('Duplicate ID');ids.add(o.id);if(![o.x,o.y,o.collider.w,o.collider.h].every(Number.isFinite)||o.collider.w<=0||o.collider.h<=0)throw Error('Invalid collider');if(!['rectangle','polygon'].includes(o.collider.shape))throw Error('Invalid collider shape');if(o.collider.shape==='polygon'&&(!o.collider.points||o.collider.points.length<3||!o.collider.points.every(p=>p.length===2&&p.every(Number.isFinite))))throw Error('Invalid polygon');if(o.mechanic_kind==='vertical_armor_slider'&&(!o.motion||!Number.isFinite(o.motion.amplitude_px)||Math.abs(o.motion.amplitude_px)>100||!(o.motion.period_s>=.25)||!Number.isFinite(o.motion.phase_rad)))throw Error('Invalid slider motion');if(o.mechanic_kind==='warning_drop_spike'&&(!o.timeline||!Number.isFinite(o.timeline.warning_s)||!(o.timeline.warning_duration_s>0)||!(o.timeline.fall_speed_px_s>0)||!(o.timeline.landed_duration_s>=0)))throw Error('Invalid drop timeline');if(o.mechanic_kind==='spring_wall'&&(!o.interaction||!(o.interaction.bounce_speed_px_s>0)||!(o.interaction.cooldown_s>0)))throw Error('Invalid spring interaction');}return true;}
function generate(seed,p={gap:100,bend:100,offset:0,phase:0}){let rand=rng(seed),obs=[],center=270;const base=(id,kind,x,y,w,h)=>({id,mechanic_kind:kind,route_id:'main',x,y,collider:{shape:'rectangle',w,h},effect_region:null,motion:null,timeline:null,interaction:{lethal:true},mount:'world',group_id:id,stage_id:'stage-1',sprint_id:'sprint-1',template_instance_id:'independent-v1'});
for(let i=0;i<8;i++){center=Math.max(130,Math.min(410,270+p.offset+(rand()-.5)*2*p.bend));const x=380+i*260,gap=p.gap,kind=i%3===1?'vertical_armor_slider':'fixed_armor_or_spike';for(let side=0;side<2;side++){let y=side?center+gap/2:-120,h=side?660-y:center-gap/2+120;let o=base('gate-'+i+'-'+side,kind,x,y,40,h);o.group_id='gate-'+i;if(kind==='vertical_armor_slider')o.motion={type:'sine',amplitude_px:18,period_s:3,phase_rad:p.phase+i};obs.push(o);}}
for(let i=0;i<2;i++){let x=770+i*1040,o=base('drop-'+i,'warning_drop_spike',x,25,28,32);o.collider={shape:'polygon',w:28,h:32,points:[[0,0],[28,0],[14,32]]};o.timeline={warning_s:(x-60)/VX-2.2+p.phase*.08,warning_duration_s:.65,fall_speed_px_s:260,landed_duration_s:.5};o.effect_region={x,y:0,w:28,h:540};obs.push(o);}
let s=base('spring-0','spring_wall',1060,495,160,20);s.interaction={lethal:false,bounce_speed_px_s:330,cooldown_s:.2};obs.push(s);
let map={schema:'flappy-loop-lab/1',id:'map-'+seed,seed,units:{distance:'px',time:'s',velocity:'px/s'},width:2560,height:540,route_id:'main',generator_parameters:{...p},obstacles:obs};validate(map);return map;}
function obstacles(map,tick){const t=tick*DT;return map.obstacles.map(o=>{let x=o.x,y=o.y,status='active',lethal=o.interaction.lethal!==false;if(o.mechanic_kind==='vertical_armor_slider')y+=o.motion.amplitude_px*Math.sin(t*2*Math.PI/o.motion.period_s+o.motion.phase_rad);if(o.mechanic_kind==='warning_drop_spike'){let q=o.timeline,d=t-q.warning_s-q.warning_duration_s,fall=(map.height-o.collider.h-o.y)/q.fall_speed_px_s;if(t<q.warning_s){status='idle';lethal=false;}else if(d<0){status='warning';lethal=false;}else if(d<fall){status='falling';y+=d*q.fall_speed_px_s;}else if(d<fall+q.landed_duration_s){status='landed';y=map.height-o.collider.h;}else{status='cleared';lethal=false;}}
return{id:o.id,kind:o.mechanic_kind,x,y,w:o.collider.w,h:o.collider.h,shape:o.collider.shape,points:o.collider.points,status,lethal,interaction:o.interaction};});}
function circleRect(x,y,r,o){let dx=x-Math.max(o.x,Math.min(x,o.x+o.w)),dy=y-Math.max(o.y,Math.min(y,o.y+o.h));return dx*dx+dy*dy<=r*r;}
function circlePolygon(x,y,r,o){let ps=o.points.map(p=>[p[0]+o.x,p[1]+o.y]),inside=false;for(let i=0,j=ps.length-1;i<ps.length;j=i++){let a=ps[i],b=ps[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside;let dx=b[0]-a[0],dy=b[1]-a[1],u=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy||1)));if((x-a[0]-u*dx)**2+(y-a[1]-u*dy)**2<=r*r)return true;}return inside;}
const hits=(x,y,o)=>o.shape==='polygon'?circlePolygon(x,y,R,o):circleRect(x,y,R,o);
function createState(map){validate(map);return{tick:0,x:60,y:270,vy:0,alive:true,won:false,events:[],cooldowns:{},main_progress_px:0,main_time_s:0};}
function step(map,s,flap){if(!s.alive||s.won)return s;if(flap)s.vy=FLAP;const previous=obstacles(map,s.tick),next=obstacles(map,s.tick+1);let maxMotion=0;for(let i=0;i<next.length;i++)maxMotion=Math.max(maxMotion,Math.abs(next[i].y-previous[i].y));let n=Math.max(2,Math.ceil((Math.abs(s.vy)*DT+G*DT*DT+VX*DT+maxMotion)/(R/2)));for(let sub=1;sub<=n;sub++){const oldY=s.y;s.vy+=G*DT/n;s.x+=VX*DT/n;s.y+=s.vy*DT/n;for(let i=0;i<next.length;i++){let o={...next[i],y:previous[i].y+(next[i].y-previous[i].y)*sub/n};if(o.status==='cleared'||o.status==='idle'||o.status==='warning')continue;if(!hits(s.x,s.y,o))continue;if(o.kind==='spring_wall'){if((s.cooldowns[o.id]??-1)<=s.tick){const top=oldY<o.y+o.h/2;s.vy=top?-o.interaction.bounce_speed_px_s:o.interaction.bounce_speed_px_s;s.y=top?o.y-R-.01:o.y+o.h+R+.01;s.cooldowns[o.id]=s.tick+Math.ceil(o.interaction.cooldown_s/DT);s.events.push({tick:s.tick,type:'bounce',id:o.id,side:top?'top':'bottom'});}}else if(o.lethal){s.alive=false;s.events.push({tick:s.tick,type:'death',id:o.id});break;}}if(s.y<R||s.y>map.height-R){s.alive=false;s.events.push({tick:s.tick,type:'death',id:'boundary'});}if(!s.alive)break;}s.tick++;s.main_time_s=s.tick*DT;s.main_progress_px=s.x-60;if(s.alive&&s.x>=map.width)s.won=true;return s;}
// Observation contains current visible collider geometry only; no map future/timelines.
function observation(map,s){return{player:{x:s.x,y:s.y,vy:s.vy},height:map.height,obstacles:obstacles(map,s.tick).filter(o=>o.x+o.w>=s.x-R&&o.x<=s.x+520).map(o=>({id:o.id,kind:o.kind,x:o.x,y:o.y,w:o.w,h:o.h,status:o.status,lethal:o.lethal}))};}
function act(obs){let p=obs.player,rects=obs.obstacles.filter(o=>o.lethal&&o.kind!=='warning_drop_spike'&&o.x+o.w>=p.x-R),target=270,minTarget=30;if(rects.length){let nearest=Math.min(...rects.map(o=>o.x));let gate=rects.filter(o=>Math.abs(o.x-nearest)<5),top=10,bottom=530;for(let o of gate){if(o.y<0)top=Math.max(top,o.y+o.h+R+8);else bottom=Math.min(bottom,o.y-R-8);}target=(top+bottom)/2;minTarget=top+25;}return p.y+p.vy*.14>target+9&&p.vy>-100;}
const bot=(map,s)=>act(observation(map,s));
function rollout(map){let s=createState(map),flaps=0;while(s.alive&&!s.won&&s.tick<3000){let a=bot(map,s);if(a)flaps++;step(map,s,a);}return{progress:Math.min(1,s.main_progress_px/(map.width-60)),success:+s.won,flaps,bounces:s.events.filter(e=>e.type==='bounce').length,death:s.events.find(e=>e.type==='death')?.id??null};}
const api={DT,R,VX,G,FLAP,registry,rng,validate,generate,obstacles,circleRect,circlePolygon,createState,step,observation,act,bot,rollout};if(typeof module!=='undefined')module.exports=api;root.FlappyLab=api;
})(typeof globalThis!=='undefined'?globalThis:this);
